/**
 * Requirements of TRUCK_v2.adia, taken from the two engine-controller documents the user supplied:
 *   SWRS  D-Motor-ECU-SWRS-001 v3.0 (D-Motor ECU Embedded Software Requirements)
 *   SPEC  MR-PLD U1-U4 Memory and CAN Specification (device specification of the MR main PCB)
 * The MR of the documents is the MCM of the truck model and the FR is the CPC.
 *
 * `by`   ids of the blocks that satisfy the requirement (SW blocks sw-*, MR hardware blocks blk_*)
 * `from` the MR system requirements (REQ-xxx of the MR-PLD model) the requirement is derived from
 */
export interface DocReq { id: string; name: string; text: string; pri: 1 | 2 | 3; by: string[]; from?: string[] }

